// helper: control with an element id
const c = (id, name, type, does, inputs = "", def = "", notes = "", extra = {}) => ({ id, sel: `#${id}`, name, type, does, inputs, def, notes, file: HTML, find: `id="${id}"`, ...extra });
// helper: control addressed by a selector + explicit find text
const s = (id, sel, name, type, does, inputs, def, notes, file, find) => ({ id, sel, name, type, does, inputs, def, notes, file, find });
// helper: control with no on-screen selector (native / command line)
const n = (id, name, type, does, inputs, def, notes, file, find) => ({ id, sel: null, name, type, does, inputs, def, notes, file, find });

